A1lib.identifyApp("appconfig.json");

const HISTORY_KEY = "arch_research_history";
const RESEARCH_TIMER_KEY = "arch_research_next_available";
const RESEARCH_DURATION_MS = (14 * 60 + 38) * 60 * 1000; // 14h 38m

let rsBind = null;
let timerInterval = null;
let researchTooltipShown = false;


// -------------------------
// Timer logic
// -------------------------
function startResearchCooldown(fromTimestamp = Date.now()) {
  const nextAt = fromTimestamp + RESEARCH_DURATION_MS;
  localStorage.setItem(RESEARCH_TIMER_KEY, String(nextAt));
  renderResearchTimer(); // immediate update
}

function formatDuration(ms) {
  if (ms <= 0) return "Ready!";

  const totalSec = Math.floor(ms / 1000);
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;

  const pad = (n) => String(n).padStart(2, "0");
  return `${h}:${pad(m)}:${pad(s)}`;
}

function renderResearchTimer() {
  const el = document.getElementById("researchTimer");
  if (!el) return;

  const nextAtStr = localStorage.getItem(RESEARCH_TIMER_KEY);
  if (!nextAtStr) {
    el.textContent = "Not started";
    return;
  }

  const nextAt = Number(nextAtStr);
  const now = Date.now();
  const remaining = nextAt - now;

  if (remaining <= 0) {
    el.textContent = "Ready!";

    if (!researchTooltipShown) {
      alt1.setTooltip("Research ready!");
      researchTooltipShown = true;
    }
    return;
  }
  researchTooltipShown = false;
  alt1.clearTooltip()
  const readyAt = new Date(nextAt).toLocaleString();
  el.textContent = `${formatDuration(remaining)} (ready at ${readyAt})`;
}


function initResearchTimerLoop() {
  if (timerInterval) clearInterval(timerInterval);

  renderResearchTimer();
  timerInterval = setInterval(renderResearchTimer, 1000);
}

document.getElementById("startTimerBtn")?.addEventListener("click", () => {
  startResearchCooldown(Date.now());
});

initResearchTimerLoop();

// -------------------------
// Init UI
// -------------------------
window.addEventListener("DOMContentLoaded", () => {
  // Buttons
  document.getElementById("scanBtn").addEventListener("click", scan);
  document.getElementById("historyBtn").addEventListener("click", openHistory);
  document.getElementById("closeHistoryBtn").addEventListener("click", closeHistory);

  const modal = document.getElementById("historyModal");
  modal.addEventListener("click", (e) => {
    if (e.target === modal) closeHistory();
  });

  const modalContent = modal.querySelector(".modalContent");
  if (modalContent) modalContent.addEventListener("click", (e) => e.stopPropagation());

  document.getElementById("historyList").addEventListener("click", (e) => {
    const btn = e.target.closest("button[data-del]");
    if (!btn) return;

    e.stopPropagation();

    const state = btn.getAttribute("data-state") || "idle";
    const ts = Number(btn.getAttribute("data-del"));

    if (state === "idle") {
      btn.textContent = "Confirm";
      btn.setAttribute("data-state", "confirm");
      btn.classList.add("danger");
      setTimeout(() => {
        if (btn.getAttribute("data-state") === "confirm") {
          btn.textContent = "Delete";
          btn.setAttribute("data-state", "idle");
          btn.classList.remove("danger");
          btn.classList.add("small");
        }
      }, 3500);

      return;
    }

    deleteRecordByTimestamp(ts);
  });

  refreshStats();
});

// -------------------------
// Scan: find window -> build slots -> match items -> read qty
// -------------------------
function scan() {
  // Safety: make sure artefact data is loaded
  if (!artefactData || !artefactData.artefacts) {
    console.warn("Artefact data not loaded yet");
    return;
  }

  rsBind = alt1.bindRegion(0, 0, alt1.rsWidth, alt1.rsHeight);

  const researchMatches = JSON.parse(
    alt1.bindFindSubImg(
      rsBind,
      RESEARCH_ICON,
      149,
      0,
      0,
      alt1.rsWidth,
      alt1.rsHeight
    )
  );

  const research = researchMatches[0];
  if (!research) {
    console.log("Research interface not found");
    return;
  }

  // Top-left of inner loot window
  const baseX = research.x - 139;
  const baseY = research.y + 30;

  // Grid cell size
  const cellW = 54;
  const cellH = 43;

  // Build slots (8x4)
  const slots = [];
  let index = 0;
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 8; col++) {
      slots.push({
        index,
        x: baseX + col * cellW,
        y: baseY + row * cellH
      });
      index++;
    }
  }

  const results = [];

  // Convert artefact map -> array once
  const artefacts = Object.values(artefactData.artefacts);
  console.log(artefacts[0].icon_damaged_base64)
  console.log(artefacts[0].icon_width)

  for (const slot of slots) {
    let found = null;

    for (const art of artefacts) {
      if (!art.icon_damaged_base64 || !art.icon_width) continue;

      const matchArr = JSON.parse(
        alt1.bindFindSubImg(
          rsBind,
          art.icon_damaged_base64,
          art.icon_width,
          slot.x,
          slot.y,
          cellW,
          cellH
        )
      );

      if (Array.isArray(matchArr) && matchArr.length > 0) {
        found = art;
        break;
      }
    }

    if (!found) continue;

    // Highlight slot
    alt1.overLayRect(0xFF00FF00, slot.x, slot.y, cellW, cellH, 800, 1);

    const qty = readStackAt(slot.x, slot.y);

    results.push({
      slotIndex: slot.index,
      item: found.name,
      category: "artefact",
      qty,
      tetraWorth: found.tetraWorth ?? 0
    });
  }

  saveScan(results);
  startResearchCooldown(Date.now());
  refreshStats();

  if (isHistoryOpen()) renderHistoryModal();
}


// -------------------------
// History modal
// -------------------------
function openHistory() {
  renderHistoryModal();
  document.getElementById("historyModal").style.display = "block";
}

function closeHistory() {
  document.getElementById("historyModal").style.display = "none";
}

function isHistoryOpen() {
  return document.getElementById("historyModal").style.display === "block";
}

function renderHistoryModal() {
  const list = document.getElementById("historyList");
  const history = loadHistory();

  if (!history.length) {
    list.innerHTML = "<p>No scans yet.</p>";
    return;
  }

  const view = [...history].sort((a, b) => b.timestamp - a.timestamp);

  list.innerHTML = view.map(rec => `
    <div class="scanCard">
      <div class="scanCardTop">
        <div>
          <b>${escapeHtml(rec.date)}</b>
          <div style="font-size:11px;opacity:.8;">Items: ${rec.items.length}</div>
        </div>
        <div class="actions">
          <button data-del="${rec.timestamp}" data-state="idle">Delete</button>
        </div>
      </div>

      <table>
        <thead><tr><th>Slot</th><th>Item</th><th>Qty</th></tr></thead>
        <tbody>
          ${rec.items.map(it => `
            <tr>
              <td>${it.slotIndex}</td>
              <td>${escapeHtml(it.item)}</td>
              <td>${it.qty}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `).join("");
}

function deleteRecordByTimestamp(timestamp) {
  const history = loadHistory();
  const idx = history.findIndex(r => Number(r.timestamp) === Number(timestamp));
  if (idx === -1) return;

  history.splice(idx, 1);
  localStorage.setItem(HISTORY_KEY, JSON.stringify(history));

  refreshStats();
  renderHistoryModal();
}

// -------------------------
// Compute stats
// -------------------------
function refreshStats() {
  const history = loadHistory();
  const stats = computeStats(history);
  renderStats(stats);
}

function computeStats(history) {
  const stats = {
    totalRecords: history.length,
    avgMaterials: 0,
    avgArtefacts: 0,
    avgMaterialsPerSlot: 0,
    avgTetraPerScan: 0,
    itemStats: {},
    mostCommon: [],
    bestScan: null
  };

  if (!history.length) return stats;

  let totalMaterials = 0;
  let totalArtefacts = 0;
  let bestScore = -1;

  let materialsPerSlotSum = 0;
  let materialsPerSlotScans = 0;
    let totalTetraValue = 0;


  for (const scan of history) {
    let scanMaterials = 0;
    let scanArtefacts = 0;
let scanTetraValue = 0;
    let scanMaterialSlots = 0;

    for (const it of scan.items) {
      const qty = Number(it.qty) || 0;
      const name = it.item;
      const cat = it.category;
      const tetra = Number(it.tetraWorth) || 0;
      console.log(tetra)
        scanTetraValue += tetra;

      if (!stats.itemStats[name]) {
        stats.itemStats[name] = {
          name,
          category: cat,
          total: 0,
          count: 0,
          min: Infinity,
          max: 0
        };
      }

      const s = stats.itemStats[name];
      s.total += qty;
      s.count += 1;
      s.min = Math.min(s.min, qty);
      s.max = Math.max(s.max, qty);


      if (cat === "materials") {
        scanMaterials += qty;
        scanMaterialSlots += 1; // NEW
      }

      if (cat === "artefact") scanArtefacts += 1;
    }

            totalTetraValue += scanTetraValue;
    console.log(totalTetraValue)

    if (scanMaterialSlots > 0) {
      materialsPerSlotSum += (scanMaterials / scanMaterialSlots);
      materialsPerSlotScans += 1;
    }

    totalMaterials += scanMaterials;
    totalArtefacts += scanArtefacts;

    if (scanMaterials > bestScore) {
      bestScore = scanMaterials;
      stats.bestScan = {
        date: scan.date,
        materials: scanMaterials,
        artefacts: scanArtefacts
      };
    }
  }

  stats.avgMaterials = totalMaterials / history.length;
  stats.avgArtefacts = totalArtefacts / history.length;

  stats.avgMaterialsPerSlot = materialsPerSlotScans > 0
    ? (materialsPerSlotSum / materialsPerSlotScans)
    : 0;

    stats.avgTetraPerScan =
  history.length > 0
    ? totalTetraValue / history.length
    : 0;

  const CATEGORY_ORDER = {
    materials: 0,
    artefact: 1,
    tetracompas: 2
  };

  stats.mostCommon = Object.values(stats.itemStats)
    .map(s => ({
      name: s.name,
      category: s.category,
      appearPct: (s.count / history.length) * 100,
      min: s.min,
      avg: s.total / s.count,
      max: s.max
    }))
    .sort((a, b) => {
      const ca = CATEGORY_ORDER[a.category] ?? 99;
      const cb = CATEGORY_ORDER[b.category] ?? 99;
      if (ca !== cb) return ca - cb;
      if (b.avg !== a.avg) return b.avg - a.avg;
      return a.name.localeCompare(b.name);
    });

  return stats;
}


function renderStats(stats) {
  const el = document.getElementById("averages");

  if (!stats.totalRecords) {
    el.innerHTML = `
      <div class="scanCard">
        <h3>Overview</h3>
        <div><b>Total records:</b> 0</div>
        <div>No scans yet.</div>
      </div>
    `;
    return;
  }

  el.innerHTML = `
    <div class="scanCard">
      <h3>Overview</h3>
      <div><b>Total research records:</b> ${stats.totalRecords}</div>
      <div><b>Avg materials / research:</b> ${stats.avgMaterials.toFixed(1)}</div>
      <div><b>Avg materials per slot:</b> ${stats.avgMaterialsPerSlot.toFixed(2)}</div>
      <div><b>Avg artefacts / research:</b> ${stats.avgArtefacts.toFixed(2)}</div>
      <div><b>Avg tetra pieces / research:</b> ${stats.avgTetraPerScan.toFixed(2)}</div>
      <div><b>Best research:</b> ${stats.bestScan.materials} materials (${escapeHtml(stats.bestScan.date)})</div>
    </div>

    <div class="scanCard">
      <h3>Most common items</h3>
      <table>
        <thead>
          <tr>
            <th>Item</th>
            <th>Appear %</th>
            <th>Min</th>
            <th>Avg</th>
            <th>Max</th>
          </tr>
        </thead>
        <tbody>
          ${stats.mostCommon.map(i => `
            <tr>
              <td>${escapeHtml(i.name)}</td>
              <td>${i.appearPct.toFixed(1)}%</td>
              <td>${i.min}</td>
              <td>${i.avg.toFixed(1)}</td>
              <td>${i.max}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    </div>
  `;
}

// -------------------------
// helpers
// -------------------------
function loadHistory() {
  return JSON.parse(localStorage.getItem(HISTORY_KEY) || "[]");
}

function saveScan(results) {
  const history = loadHistory();
  const now = new Date();

  history.push({
    timestamp: now.getTime(),
    date: now.toLocaleString(),
    items: results
  });

  localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  }[c]));
}



// -------------------------
// Stack OCR via column counting
// -------------------------

function decodeBgraBase64(b64) {
  const bin = atob(b64);
  const len = bin.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function getPixelFromBGRA(buf, w, x, y) {
  const i = (y * w + x) * 4;
  const b = buf[i];
  const g = buf[i + 1];
  const r = buf[i + 2];
  const a = buf[i + 3];
  return (a << 24) | (r << 16) | (g << 8) | b;
}

const NUM_BOX = { offX: 2, offY: 1, w: 54, h: 12 };

function isStackPixel(r, g, b, a) {
  if (a < 40) return false;
  return r >= 245 && g >= 245 && b <= 20;
}
function classifyDigit(pixelCount, longestStreak) {
  if (pixelCount === 14) return "0";

  if (pixelCount === 11) return longestStreak < 6 ? "7" : "1";

  if (pixelCount === 13) return longestStreak === 3 ? "3" : "4";

  if (pixelCount === 15) {
    if (longestStreak === 2) return "2";
    if (longestStreak === 4) return "5";
    if (longestStreak >= 7) return "9";
  }

  if (pixelCount === 18) return "6";
  if (pixelCount >= 19) return "8";

  return "";
}

function readStackAt(slotX, slotY) {
  const x0 = slotX // (slotX + NUM_BOX.offX) | 0;
  const y0 = slotY //(slotY + NUM_BOX.offY) | 0;
  const w = 54 // NUM_BOX.w | 0;
  const h = 43 //NUM_BOX.h | 0;

  // Debug box
  alt1.overLayRect(0xFFFF0000, x0, y0, w, h, 7000, 1);

  const b64 = alt1.bindGetRegion(rsBind, x0, y0, w, h);
  if (!b64) return 0;

  const buf = decodeBgraBase64(b64);

  let digits = "";
  let emptyCols = 0;

  let inDigit = false;
  let accCount = 0;
  let accMaxStreak = 0;

  for (let xx = 0; xx < w; xx++) {
    let colCount = 0;
    let colMaxStreak = 0;
    let streak = 0;

    for (let yy = 0; yy < h; yy++) {
      const argb = getPixelFromBGRA(buf, w, xx, yy);

      const a = (argb >>> 24) & 0xFF;
      const r = (argb >>> 16) & 0xFF;
      const g = (argb >>> 8) & 0xFF;
      const b = argb & 0xFF;

      if (isStackPixel(r, g, b, a)) {
        colCount++;
        streak++;
        if (streak > colMaxStreak) colMaxStreak = streak;
      } else {
        streak = 0;
      }
    }

    if (colCount === 0) {
      if (inDigit) {
        const d = classifyDigit(accCount, accMaxStreak);
        if (d) digits += d;

        inDigit = false;
        accCount = 0;
        accMaxStreak = 0;
      }

      emptyCols++;
      if (emptyCols >= 15) break;
      continue;
    }

    emptyCols = 0;
    inDigit = true;
    accCount += colCount;
    if (colMaxStreak > accMaxStreak) accMaxStreak = colMaxStreak;
  }

  if (inDigit) {
    const d = classifyDigit(accCount, accMaxStreak);
    if (d) digits += d;
  }

  return digits ? parseInt(digits, 10) : 1;
}